#!/usr/bin/env python3
"""
Black Element Killer - Specific targeting for remaining black/dark areas
"""

import streamlit as st

def apply_black_element_killer():
    """Apply specific CSS to eliminate black text areas and chart backgrounds"""
    st.markdown("""
    <style>
        /* === BLACK ELEMENT KILLER CSS === */
        
        /* === DROPDOWN TEXT AREA FIXES === */
        /* Text formatting and areas around text in dropdowns */
        .stSelectbox span,
        .stSelectbox div span,
        .stSelectbox > div > div span,
        .stSelectbox > div > div > div span,
        .stMultiSelect span,
        .stMultiSelect div span,
        .stMultiSelect > div > div span {\n            background-color: transparent !important;\n            background: transparent !important;\n            color: #1f2937 !important;\n        }\n        \n        /* Dropdown input containers */\n        .stSelectbox > div > div,\n        .stSelectbox > div > div > div,\n        .stMultiSelect > div > div,\n        .stMultiSelect > div > div > div {\n            background-color: #FFFFFF !important;\n            background: #FFFFFF !important;\n            color: #1f2937 !important;\n        }\n        \n        /* Dropdown arrow containers and SVG elements */\n        .stSelectbox svg,\n        .stMultiSelect svg,\n        .stSelectbox svg path,\n        .stMultiSelect svg path,\n        [data-baseweb=\"select\"] svg,\n        [class*=\"indicatorContainer\"],\n        [class*=\"indicatorContainer\"] svg {\n            background-color: transparent !important;\n            background: transparent !important;\n            color: #6b7280 !important;\n            fill: #6b7280 !important;\n        }\n        \n        /* Text input areas within dropdowns */\n        .stSelectbox input,\n        .stMultiSelect input,\n        [data-baseweb=\"select\"] input,\n        input[role=\"combobox\"] {\n            background-color: transparent !important;\n            background: transparent !important;\n            color: #1f2937 !important;\n        }\n        \n        /* === CHART BACKGROUND NUCLEAR FIX === */\n        /* Target ALL possible Plotly chart elements */\n        .js-plotly-plot,\n        .js-plotly-plot *,\n        .js-plotly-plot .plotly,\n        .js-plotly-plot .plotly *,\n        .js-plotly-plot .plot-container,\n        .js-plotly-plot .plot-container *,\n        .js-plotly-plot .main-svg,\n        .js-plotly-plot .bg,\n        .plotly,\n        .plotly *,\n        .plotly .bg,\n        .plot-container,\n        .plot-container *,\n        .plot-container .bg,\n        div.plotly-graph-div,\n        div.plotly-graph-div *,\n        div.plotly-graph-div > div,\n        div.plotly-graph-div > div * {\n            background-color: #FFFFFF !important;\n            background: #FFFFFF !important;\n        }\n        \n        /* Chart SVG elements */\n        .js-plotly-plot svg,\n        .js-plotly-plot svg *,\n        svg.main-svg,\n        svg.main-svg *,\n        .js-plotly-plot .plotly svg,\n        .js-plotly-plot .plotly svg * {\n            background-color: #FFFFFF !important;\n            background: #FFFFFF !important;\n            fill: #FFFFFF !important;\n        }\n        \n        /* Chart backgrounds and paper */\n        .js-plotly-plot .plotly .paper,\n        .js-plotly-plot .plotly .plot,\n        .js-plotly-plot rect,\n        .plotly rect,\n        svg rect[class*=\"bg\"],\n        svg rect[fill=\"#FFFFFF\"],\n        g.paper {\n            background-color: #FFFFFF !important;\n            background: #FFFFFF !important;\n            fill: #FFFFFF !important;\n        }\n        \n        /* Chart text elements */\n        .js-plotly-plot text,\n        .js-plotly-plot .plotly text,\n        svg.main-svg text,\n        .plotly text {\n            fill: #1f2937 !important;\n            color: #1f2937 !important;\n        }\n        \n        /* === STREAMLIT CHART CONTAINERS === */\n        .stPlotlyChart,\n        .stPlotlyChart *,\n        .stPlotlyChart > div,\n        .stPlotlyChart > div * {\n            background-color: #FFFFFF !important;\n            background: #FFFFFF !important;\n        }\n        \n        /* === UNIVERSAL BLACK KILLER === */\n        /* Target any element with black background */\n        [style*=\"background-color: black\"],\n        [style*=\"background: black\"],\n        [style*=\"background-color: #000000\"],\n        [style*=\"background: #000000\"],\n        [style*=\"background-color: #000\"],\n        [style*=\"background: #000\"],\n        [style*=\"background-color: rgb(0, 0, 0)\"],\n        [style*=\"background: rgb(0, 0, 0)\"],\n        [style*=\"background-color:black\"],\n        [style*=\"background:black\"] {\n            background-color: #FFFFFF !important;\n            background: #FFFFFF !important;\n            color: #1f2937 !important;\n        }\n        \n        /* === NUCLEAR TEXT OVERRIDE === */\n        /* Force correct colors on all text elements */\n        span,\n        div,\n        p,\n        input,\n        textarea,\n        label {\n            color: inherit !important;\n        }\n        \n        /* Ensure no element has a black background by default */\n        * {\n            background-color: inherit !important;\n        }\n        \n        /* === PLOTLY SPECIFIC OVERRIDES === */\n        /* Nationality chart and other charts */\n        .user-select-none,\n        .svg-container,\n        .plot-container.plotly {\n            background-color: #FFFFFF !important;\n            background: #FFFFFF !important;\n        }\n        \n        /* Chart modebar */\n        .modebar,\n        .modebar *,\n        .modebar-container,\n        .modebar-group {\n            background-color: #FFFFFF !important;\n            background: #FFFFFF !important;\n        }\n        \n        .modebar-btn {\n            background-color: #f8f9fa !important;\n            color: #1f2937 !important;\n        }\n    </style>\n    """, unsafe_allow_html=True)